3	/**
4	 * Canonical AI metadata extracted from a span's OpenTelemetry GenAI semantic
5	 * convention (`gen_ai.*`) attributes.
6	 *
7	 * The fields below are an explicit **allowlist**: only these are ever read from
8	 * a span (see {@link FIELD_SPECS}). Anything not mapped — prompt/response
9	 * content, messages, tool calls, embeddings payloads, and other
10	 * potentially-sensitive or bulky attributes — is not captured.
11	 *
12	 * For each category we describe how multiple AIMetadata values are aggregated
13	 * (see {@link aggregate}).
14	 */
15	export interface AIMetadata {
16	  // Identity & classification (last-write-wins).
17	
18	  /** The requested model, e.g. `gpt-4.1-nano`. */
19	  requestModel?: string;
20	  /**
21	   * The model that actually served the request. This is often a dated snapshot
22	   * of the requested {@link AIMetadata.requestModel} (e.g.
23	   * `gpt-4.1-nano-2025-04-14`).
24	   */
25	  responseModel?: string;
26	  /** The AI provider that served the request (e.g. `openai`) */
27	  provider?: string;
28	  /**
29	   * The kind of operation performed, e.g. `chat`, `text_completion`,
30	   * `embeddings`. Last-write-wins across calls.
31	   */
32	  operationName?: string;
33	  /** The provider's identifier for the response, e.g. `chatcmpl-...`. */
34	  responseId?: string;
35	  /**
36	   * Why generation stopped, as reported by the provider, e.g. `["stop"]`,
37	   * `["length"]`, or `["tool_calls"]`. Last-write-wins across calls.
38	   */
39	  finishReasons?: string[];
40	
41	  // Token usage (summed).
42	
43	  /** The number of input tokens consumed by the request. */
44	  inputTokens?: number;
45	  /** The number of output tokens produced by the response. */
46	  outputTokens?: number;
47	  /** The total tokens consumed, as reported by the provider. */
48	  totalTokens?: number;
49	  /**
50	   * Cached input tokens read from the prompt cache. Providers differ on
51	   * accounting. OpenAI's cached tokens are a subset of
52	   * {@link AIMetadata.inputTokens}, Anthropic's are additive. Callers must
53	   * not assume a single relationship.
54	   */
55	  cacheReadTokens?: number;
56	  /** Tokens written to the prompt cache. */
57	  cacheCreationTokens?: number;
58	  /** Reasoning/thinking tokens, when the emitter reports them separately. */
59	  reasoningTokens?: number;
60	
61	  // Request / inference parameters (last-write-wins). These describe the
62	  // request the caller made, not the response, and are stored raw as the
63	  // emitter reports them.
64	
65	  /** Sampling temperature requested, e.g. `0.7`. */
66	  temperature?: number;
67	  /** Nucleus sampling probability mass requested (`top_p`), e.g. `0.9`. */
68	  topP?: number;
69	  /** Upper bound on tokens to generate (`max_tokens`). */
70	  maxTokens?: number;
71	  /** Frequency penalty requested. */
72	  frequencyPenalty?: number;
73	  /** Presence penalty requested. */
74	  presencePenalty?: number;
75	  /** Sampling seed requested, when the emitter reports it. */
76	  seed?: number;
77	}
78	
79	type ValueType = "text" | "number" | "stringList";
80	type MergeStrategy = "replace" | "sum";
81	
82	/**
83	 * Derives the subset of AIMetadata keys whose assigned value matches TValue.
84	 *
85	 * AIMetadata fields are optional (`model?: string`), so each field's type is
86	 * effectively `string | undefined` or `number | undefined`. `Exclude` removes
87	 * `undefined` before checking the value type, and `-?` prevents optional fields
88	 * from adding `undefined` back into the final key union.
89	 */
90	type FieldsWithValue<TValue> = {
91	  [TField in keyof AIMetadata]-?: Exclude<
92	    AIMetadata[TField],
93	    undefined
94	  > extends TValue
95	    ? TField
96	    : never;
97	}[keyof AIMetadata];
98	
99	type TextField = FieldsWithValue<string>;
100	type NumberField = FieldsWithValue<number>;
101	type StringListField = FieldsWithValue<string[]>;
102	
103	interface BaseFieldSpec {
104	  /** The canonical (preferred) source `gen_ai.*` attribute key. */
105	  source: string;
106	  /**
107	   * Deprecated source keys to read when {@link BaseFieldSpec.source} is absent
108	   * or carries no usable value, in descending precedence. The preferred
109	   * {@link BaseFieldSpec.source} always wins when it supplies a value; these are
110	   * only consulted as fallbacks.
111	   */
112	  fallbackSources?: readonly string[];
113	  valueType: ValueType;
114	  merge: MergeStrategy;
115	}
116	
117	interface TextFieldSpec extends BaseFieldSpec {
118	  /** The canonical {@link AIMetadata} field this populates. */
119	  field: TextField;
120	  valueType: "text";
121	  merge: "replace";
122	}
123	
124	interface NumberFieldSpec extends BaseFieldSpec {
125	  /** The canonical {@link AIMetadata} field this populates. */
126	  field: NumberField;
127	  valueType: "number";
128	}
129	
130	interface StringListFieldSpec extends BaseFieldSpec {
131	  /** The canonical {@link AIMetadata} field this populates. */
132	  field: StringListField;
133	  valueType: "stringList";
134	  merge: "replace";
135	}
136	
137	type FieldSpec = TextFieldSpec | NumberFieldSpec | StringListFieldSpec;
138	
139	function textField(
140	  field: TextField,
141	  source: string,
142	  fallbackSources?: readonly string[],
143	): TextFieldSpec {
144	  return {
145	    field,
146	    source,
147	    fallbackSources,
148	    valueType: "text",
149	    merge: "replace",
150	  };
151	}
152	
153	function numberField(
154	  field: NumberField,
155	  source: string,
156	  merge: MergeStrategy,
157	): NumberFieldSpec {
158	  return {
159	    field,
160	    source,
161	    valueType: "number",
162	    merge,
163	  };
164	}
165	
166	function stringListField(
167	  field: StringListField,
168	  source: string,
169	): StringListFieldSpec {
170	  return {
171	    field,
172	    source,
173	    valueType: "stringList",
174	    merge: "replace",
175	  };
176	}
177	
178	/**
179	 * Every `gen_ai.*` attribute we capture, mapped to its canonical field.
180	 *
181	 * Anything not listed here (prompt/response content, messages, tool calls,
182	 * unknown keys) is ignored.
183	 */
184	export const FIELD_SPECS = [
185	  // Identity & classification.
186	  textField("requestModel", "gen_ai.request.model"),
187	  textField("responseModel", "gen_ai.response.model"),
188	  // `gen_ai.system` is the deprecated predecessor of `gen_ai.provider.name`;
189	  // the canonical key wins when both are present on a span.
190	  textField("provider", "gen_ai.provider.name", ["gen_ai.system"]),
191	  textField("operationName", "gen_ai.operation.name"),
192	  textField("responseId", "gen_ai.response.id"),
193	  stringListField("finishReasons", "gen_ai.response.finish_reasons"),
194	
195	  // Token usage.
196	  numberField("inputTokens", "gen_ai.usage.input_tokens", "sum"),
197	  numberField("outputTokens", "gen_ai.usage.output_tokens", "sum"),
198	  numberField("totalTokens", "gen_ai.usage.total_tokens", "sum"),
199	  numberField("cacheReadTokens", "gen_ai.usage.cache_read.input_tokens", "sum"),
200	  numberField(
201	    "cacheCreationTokens",
202	    "gen_ai.usage.cache_creation.input_tokens",
203	    "sum",
204	  ),
205	  numberField("reasoningTokens", "gen_ai.usage.reasoning.output_tokens", "sum"),
206	
207	  // Request / inference parameters. These describe the request, not a quantity,
208	  // so they replace rather than sum when a step makes several calls.
209	  numberField("temperature", "gen_ai.request.temperature", "replace"),
210	  numberField("topP", "gen_ai.request.top_p", "replace"),
211	  numberField("maxTokens", "gen_ai.request.max_tokens", "replace"),
212	  numberField(
213	    "frequencyPenalty",
214	    "gen_ai.request.frequency_penalty",
215	    "replace",
216	  ),
217	  numberField("presencePenalty", "gen_ai.request.presence_penalty", "replace"),
218	  numberField("seed", "gen_ai.request.seed", "replace"),
219	] as const satisfies readonly FieldSpec[];
220	
221	function parseNumericAttribute(value: unknown): number | undefined {
222	  if (typeof value === "number") {
223	    return Number.isFinite(value) ? value : undefined;
224	  }
225	
226	  if (typeof value !== "string" || value === "") {
227	    return undefined;
228	  }
229	
230	  const num = Number(value);
231	  return Number.isFinite(num) ? num : undefined;
232	}
233	
234	/**
235	 * Coerces an attribute to a list of non-empty strings, or `undefined` when it
236	 * yields none. OTLP arrays may carry non-string or empty entries; those are
237	 * dropped, and an array that reduces to nothing is treated as absent.
238	 */
239	function parseStringListAttribute(value: unknown): string[] | undefined {
240	  const items = Array.isArray(value) ? value : [value];
241	  const strings = items.filter(
242	    (item): item is string => typeof item === "string" && item !== "",
243	  );
244	  return strings.length > 0 ? strings : undefined;
245	}
246	
247	/**
248	 * Extracts {@link AIMetadata} from a span's attributes.
249	 *
250	 * Only the allowlisted {@link FIELD_SPECS} are read. Every other attribute is
251	 * ignored. Numeric fields accept numbers and quoted numeric strings and are
252	 * otherwise dropped, as OTLP/JSON may encode int64 as a quoted string. Text
253	 * fields are dropped when empty. String-list fields keep only non-empty string
254	 * entries and are dropped when none remain.
255	 *
256	 * Returns an empty object for spans carrying no recognised `gen_ai.*`
257	 * attributes.
258	 *
259	 * @param attributes - The span attributes, as exposed by
260	 * `ReadableSpan.attributes`.
261	 */
262	export const extractAIMetadataFromAttributes = (
263	  attributes: Attributes,
264	): AIMetadata => {
265	  const metadata: AIMetadata = {};
266	
267	  for (const spec of FIELD_SPECS) {
268	    // Read the canonical key first, then any deprecated fallbacks in order,
269	    // taking the first that yields a usable value.
270	    const sources = [spec.source, ...(spec.fallbackSources ?? [])];
271	
272	    for (const source of sources) {
273	      const value = attributes[source];
274	      if (value === undefined) {
275	        continue;
276	      }
277	
278	      if (spec.valueType === "text") {
279	        const text = typeof value === "string" ? value : String(value);
280	        if (text !== "") {
281	          metadata[spec.field] = text;
282	          break;
283	        }
284	      } else if (spec.valueType === "stringList") {
285	        const list = parseStringListAttribute(value);
286	        if (list !== undefined) {
287	          metadata[spec.field] = list;
288	          break;
289	        }
290	      } else {
291	        const num = parseNumericAttribute(value);
292	        if (num !== undefined) {
293	          metadata[spec.field] = num;
294	          break;
295	        }
296	      }
297	    }
298	  }
299	
300	  return metadata;
301	};
302	
303	/**
304	 * Aggregates two {@link AIMetadata} values, folding a later call's metadata into
305	 * an earlier accumulator for a single step.
306	 *
307	 * - Token-count fields (`merge: "sum"`) are **summed**, so a step that makes
308	 *   several LLM calls reports their combined usage.
309	 * - Every other field uses `merge: "replace"` (`b` overwrites `a`)
310	 *
311	 * A field is present in the result only when at least one input supplies it.
312	 *
313	 * @param a - The accumulator (earlier calls).
314	 * @param b - The later metadata, whose values win on conflict (and add for sums).
315	 */
316	export const aggregate = (a: AIMetadata, b: AIMetadata): AIMetadata => {
317	  const out: AIMetadata = { ...a };
318	
319	  for (const spec of FIELD_SPECS) {
320	    if (spec.valueType === "number") {
321	      const bValue = b[spec.field];
322	      if (bValue === undefined) {
323	        continue;
324	      }
325	
326	      if (spec.merge === "sum") {
327	        out[spec.field] = (out[spec.field] ?? 0) + bValue;
328	      } else {
329	        out[spec.field] = bValue;
330	      }
331	    } else if (spec.valueType === "text") {
332	      // Text fields are always replace.
333	      const bValue = b[spec.field];
334	      if (bValue === undefined) {
335	        continue;
336	      }
337	      out[spec.field] = bValue;
338	    } else {
339	      // String-list fields are always replace.
340	      const bValue = b[spec.field];
341	      if (bValue === undefined) {
342	        continue;
343	      }
344	      out[spec.field] = bValue;
345	    }
346	  }
347	
348	  return out;
349	};
350	
351	/** Converts a canonical camelCase field name to the server's snake_case key. */
352	const toSnakeCase = (field: string): string =>
353	  field.replace(/[A-Z]/g, (char) => `_${char.toLowerCase()}`);
354	
355	/**
356	 * Maps an {@link AIMetadata} value onto the server's `inngest.ai` metadata
357	 * values, converting each canonical camelCase field to snake_case (e.g.
358	 * `inputTokens` → `input_tokens`). Returns `undefined` when there is nothing to
359	 * emit so callers can skip stamping metadata entirely.
360	 */
361	export const toInngestAIMetadataValues = (
362	  metadata: AIMetadata,
363	): Record<string, unknown> | undefined => {
364	  const entries = Object.entries(metadata);
365	  if (entries.length === 0) {
366	    return undefined;
367	  }
368	
369	  const values: Record<string, unknown> = {};
370	  for (const [field, value] of entries) {
371	    values[toSnakeCase(field)] = value;
372	  }
373	
374	  return values;
375	};
