 * one other field was extracted, so spans without recognised `gen_ai.*`
 * attributes yield an empty object.
 *
 * @param span - The span; only `attributes`, `startTime` and `endTime` are
 * read.
 */
export const extractAIMetadataFromSpan = (span: ReadableSpan): AIMetadata => {
  const attributes: Attributes = span.attributes ?? {};
  const metadata: AIMetadata = {};

  for (const spec of FIELD_SPECS) {
    if (spec.field === "latencyMs") {
      continue;
    }

    // Read the canonical key first, then any deprecated fallbacks in order,
    // taking the first that yields a usable value.
    const sources = [
      ...(spec.source ? [spec.source] : []),
      ...(("fallbackSources" in spec && spec.fallbackSources) || []),
    ];

    for (const source of sources) {
      const value = attributes[source];
      if (value === undefined) {
        continue;
      }

      if (spec.valueType === "text") {
        const text = typeof value === "string" ? value : String(value);
        if (text !== "") {
          metadata[spec.field] = text;
          break;
        }
      } else if (spec.valueType === "stringList") {
        const list = parseStringListAttribute(value);
        if (list !== undefined) {
          metadata[spec.field] = list;
          break;
        }
      } else {
        const num = parseNumericAttribute(value);
        if (num !== undefined) {
          metadata[spec.field] = num;
          break;
        }
      }
    }
  }

  if (Object.keys(metadata).length > 0 && span.startTime && span.endTime) {
    const latencyMs = hrTimeToMs(span.endTime) - hrTimeToMs(span.startTime);
    if (Number.isFinite(latencyMs)) {
      metadata.latencyMs = latencyMs;
    }
  }

  return metadata;
};

